WS. The ingest cuts a new entry's stills into
 * the repo's public/ at 21:30; Vercel gets that directory at 00:30. A row carrying a repo path
 * would render a broken picture for three hours on every new entry. Uploading is the wires'
 * arrangement and it costs nothing a second time: a file is uploaded once per content hash and the
 * ledger beside this script remembers it.
 *
 * AN UNCHANGED ROW MUST NOT BUY A DATABASE WRITE. The wires learned this at 189 rows x 7 syncs a
 * day; sameRow() below is theirs. Rows are read back once per publication, bounded by that
 * publication, and only what differs is written. It fails SAFE: any doubt is a write.
 *
 * THE TABLE MIRRORS THE ADAPTER'S PUBLISHED SET. A row whose slug the adapter no longer publishes
 * is deleted, but only after a run in which every upsert for that publication succeeded: deleting
 * against a dump that failed would empty a site's feed.
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { createClient } from '@supabase/supabase-js';

const DIR = path.dirname(fileURLToPath(import.meta.url));
const OPS = path.resolve(DIR, '../..');
const PROJECTS = path.dirname(OPS);
const QUEUES = path.join(DIR, 'daemon');             // state.<lane>.json lives beside the daemon
const TSX = path.join(OPS, 'node_modules/.bin/tsx');
const DUMP = path.join(DIR, 'publication-dump.mts');
const LEDGER = path.join(DIR, '.publication-uploads.json');
const BUCKET = 'publication';
const TABLE = 'publication_posts';

const DRY = process.argv.includes('--dry');
const ONLY = process.argv.slice(2).find((a) => !a.startsWith('--'));

/** repo -> lane. The same table ops/refresh.mjs carries; the lane names the state file. */
const SITES = [
  { repo: 'still-mornings', lane: 'soft-life' },
  { repo: 'soft-money-journal', lane: 'soft-money' },
  { repo: 'usingitup', lane: 'underconsumption' },
  { repo: 'whyyourbraindoesthat', lane: 'psych-narrated' },
];

if (ONLY && !SITES.some((site) => site.repo === ONLY)) {
  console.error(`publish: unknown publication ${ONLY}; expected ${SITES.map((site) => site.repo).join(' | ')}`);
  process.exit(1);
}

// A publisher is a production writer and pruner. Its caller must name the target explicitly;
// an incomplete shell must never acquire production through a hardcoded URL or a vault fallback.
const URL = process.env.SUPABASE_URL || '';
const KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || '';
if (!URL || !KEY) {
  console.error('publish: SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY must both be supplied by the caller');
  process.exit(1);
}
const sb = createClient(URL, KEY, { auth: { persistSession: false } });

const log = (s) => console.log(`${new Date().toISOString().slice(11, 19)}  ${s}`);

/* ── the wires' unchanged-row check, verbatim in spirit ─────────────────────────────────────── */
const stable = (v) => {
  if (v === null || v === undefined) return 'null';
  if (typeof v !== 'object') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(stable).join(',') + ']';
  return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + stable(v[k])).join(',') + '}';
};
const sameRow = (prev, row) => {
  if (!prev || typeof prev !== 'object') return false;
  for (const k of Object.keys(row)) {
    if (k === 'updated_at') continue;
    if (k === 'date') {
      // timestamptz comes back in a different textual form; compare the instant
      const a = prev[k] ? Date.parse(prev[k]) : null;
      const b = row[k] ? Date.parse(row[k]) : null;
      if (a !== b) return false;
      continue;
    }
    if (stable(row[k]) !== stable(prev[k])) return false;
  }
  return true;
};

/* ── storage ───────────────────────────────────────────────────────────────────────────────── */
const CT = { '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png', '.webp': 'image/webp' };
const publicUrl = (p) => `${URL}/storage/v1/object/public/${BUCKET}/${p}`;
const ledger = fs.existsSync(LEDGER) ? JSON.parse(fs.readFileSync(LEDGER, 'utf8')) : {};
const sha = (buf) => crypto.createHash('sha256').update(buf).digest('hex').slice(0, 16);

async function upload(siteDir, publication, rel, counters) {
  if (!rel) return null;
  if (/^https?:\/\//.test(rel)) return rel;
  const src = path.join(siteDir, 'public', rel.replace(/^\//, ''));
  if (!fs.existsSync(src)) { console.warn(`  ! missing local image ${rel}`); return null; }
  const body = fs.readFileSync(src);
  const dest = `${publication}/${rel.replace(/^\//, '')}`;
  const hash = sha(body);
  if (ledger[dest] === hash) { counters.reused++; return publicUrl(dest); }
  if (DRY) { counters.uploaded++; return publicUrl(dest); }
  const contentType = CT[path.extname(src).toLowerCase()] || 'application/octet-stream';
  const { error } = await sb.storage.from(BUCKET).upload(dest, body, { contentType, upsert: true });
  if (error) { console.warn(`  ! upload ${dest}: ${error.message}`); return null; }
  ledger[dest] = hash;
  counters.uploaded++;
  return publicUrl(dest);
}

/* ── the lane's own record of the post ─────────────────────────────────────────────────────── */
function actioned(lane) {
  const p = path.join(QUEUES, `state.${lane}.json`);
  if (!fs.existsSync(p)) return {};
  try { return JSON.parse(fs.readFileSync(p, 'utf8')).actioned ?? {}; } catch { return {}; }
}
const platformOf = (u) => {
  if (!u) return null;
  if (/tiktok\.com/i.test(u)) return 'tiktok';
  if (/instagram\.com/i.test(u)) return 'instagram';
  if (/youtube\.com|youtu\.be/i.test(u)) return 'youtube';
  return null;
};

/* ── one publication ───────────────────────────────────────────────────────────────────────── */
async function publishSite(site) {
  const dir = path.join(PROJECTS, site.repo);
  if (!fs.existsSync(dir)) return { ...site, error: `no repo at ${dir}` };

  const r = spawnSync(TSX, [DUMP], { cwd: dir, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
  if (r.status !== 0) return { ...site, error: `dump failed: ${(r.stderr || '').trim().split('\n').pop()}` };
  let dump;
  try { dump = JSON.parse(r.stdout); } catch (e) { return { ...site, error: `dump unreadable: ${e.message}` }; }
  const P = dump.publication;
  const posted = actioned(site.lane);
  const rows = dump.entries.filter((e) => e.published);
  log(`→ ${site.repo} (${P}): adapter says ${dump.published} published of ${dump.total}, ${rows.length} to mirror`);

  // Current DB state for exactly this publication, never the whole table.
  const existing = new Map();
  try {
    const { data, error } = await sb.from(TABLE).select('*').eq('publication', P);
    if (error) console.warn(`  ! read-back failed (${error.message}), writing every row`);
    for (const x of data || []) existing.set(x.slug, x);
  } catch (e) { console.warn(`  ! read-back threw (${e.message}), writing every row`); }

  const counters = { uploaded: 0, reused: 0 };
  let wrote = 0, skipped = 0, failed = 0;
  const keep = new Set();
  for (const e of rows) {
    const still = await upload(dir, P, e.still, counters);
    const wide = await upload(dir, P, e.wide, counters);
    const gallery = [];
    for (const g of e.gallery ?? []) { const u = await upload(dir, P, g, counters); if (u) gallery.push(u); }
    const rec = e.clipId ? posted[`clip:${e.clipId}`] : null;
    const permalink = rec && typeof rec === 'object' ? rec.postedUrl ?? null : null;
    const row = {
      publication: P,
      slug: e.slug,
      n: e.n,
      hook: e.hook,
      narration: e.narration ?? [],
      beats: e.beats ?? [],
      caption: e.caption ?? '',
      published: true,
      date: e.date ?? null,
      ts: e.date ? (Date.parse(e.date) || 0) : 0,
      taxon: e.taxon ?? null,
      still: still ?? e.still ?? null,
      wide: wide ?? e.wide ?? null,
      gallery,
      clip_id: e.clipId ?? null,
      permalink,
      platform: platformOf(permalink),
      updated_at: new Date().toISOString(),
    };
    keep.add(row.slug);
    if (sameRow(existing.get(row.slug), row)) { skipped++; continue; }
    if (DRY) { wrote++; continue; }
    const { error } = await sb.from(TABLE).upsert(row, { onConflict: 'publication,slug' });
    if (error) { console.warn(`  ! upsert ${P}/${row.slug}: ${error.message}`); failed++; continue; }
    wrote++;
  }

  // Prune what the adapter no longer publishes, and only after a fully successful pass.
  let pruned = 0;
  if (!failed && rows.length) {
    const stale = [...existing.keys()].filter((s) => !keep.has(s));
    if (stale.length && !DRY) {
      const { error } = await sb.from(TABLE).delete().eq('publication', P).in('slug', stale);
      if (error) console.warn(`  ! prune ${P}: ${error.message}`); else pruned = stale.length;
    } else pruned = DRY ? stale.length : 0;
  }
  if (!DRY) fs.writeFileSync(LEDGER, `${JSON.stringify(ledger, null, 2)}\n`);
  log(`  ${site.repo}: ${wrote} written, ${skipped} unchanged, ${failed} failed, ${pruned} pruned; images ${counters.uploaded} uploaded, ${counters.reused} already in storage`);
  return { ...site, publication: P, wrote, skipped, failed, pruned, ...counters, rows: rows.length };
}

const results = [];
for (const site of SITES) {
  if (ONLY && site.repo !== ONLY) continue;
  try { results.push(await publishSite(site)); }
  catch (e) { results.push({ ...site, error: String(e.message).slice(0, 200) }); }
}
for (const x of results) if (x.error) log(`✗ ${x.repo}: ${x.error}`);
const bad = results.filter((x) => x.error || x.failed);
log(`done${DRY ? ' (dry)' : ''}: ${results.length - bad.length} of ${results.length} publications live`);
process.exit(bad.length ? 1 : 0);
